468	func TestArchiveCheckpointInsideIsNotAuthority(t *testing.T) {
469		s := NewStore()
470		s.Publish("acme", 0, []Policy{allowPolicy("p1", "u1", "read", "org/a", false)})
471		s.Decide("acme", request("acme", "u1", "r1", "org/a", "read"))
472		recs, cp, _ := s.AuditExport("acme", 0)
473		good, err := EncodeAuditArchive("acme", recs, cp)
474		if err != nil {
475			t.Fatal(err)
476		}
477	
478		// Re-frame the same records with a different embedded end sequence: the
479		// caller's retained checkpoint must be the one that decides.
480		rewritten := reframe(t, good, func(payload []byte) []byte {
481			// Header layout: u32 orgLen, org, u32 endSeq, u32 fpLen, fp, ...
482			pos := 4 + len("acme")
483			binary.BigEndian.PutUint32(payload[pos:pos+4], 999)
484			return payload
485		})
486		if _, err := DecodeAuditArchive(rewritten, "acme", cp); !errors.Is(err, ErrInvalidRange) {
487			t.Fatalf("altered embedded metadata must not be trusted: err = %v", err)
488		}
489	}
490	
491	// TestArchiveInconsistentDecisionIsNotArchiveDamage archives a chain that
492	// is internally valid but whose recorded decision contradicts the recorded
493	// policy: decode succeeds, and offline review reports the inconsistency.
494	func TestArchiveInconsistentDecisionIsNotArchiveDamage(t *testing.T) {
495		req := request("acme", "u1", "r1", "org/a", "read")
496		recs, cp := syntheticChain("acme", []func(int) (string, *PolicyChange, *DecisionRecord){
497			func(seq int) (string, *PolicyChange, *DecisionRecord) {
498				return AuditPolicyChange, &PolicyChange{
499					Version:  1,
500					Policies: []Policy{allowPolicy("p1", "u1", "read", "org/a", false)},
501				}, nil
502			},
503			func(seq int) (string, *PolicyChange, *DecisionRecord) {
504				return AuditDecision, nil, &DecisionRecord{
505					Request:  req,
506					Decision: Decision{Allowed: false, Reason: "matched deny policy", Matched: []string{"p1"}, Version: 1},
507				}
508			},
509		})
510		archive, err := EncodeAuditArchive("acme", recs, cp)
511		if err != nil {
512			t.Fatal(err)
513		}
514		got, err := DecodeAuditArchive(archive, "acme", cp)
515		if err != nil {
516			t.Fatalf("a decision disagreement is not archive damage: %v", err)
517		}
518		review, err := RecheckDecisionOffline("acme", got, cp, 2)
519		if err != nil {
520			t.Fatal(err)
521		}
522		if review.Consistent {
523			t.Fatal("inconsistent decision must still be reported by offline review")
524		}
525	}
526	
527	// TestArchiveIsReadOnlyAndDetached proves encode and decode mutate nothing
528	// and return values independent of their inputs and of each other.
529	func TestArchiveIsReadOnlyAndDetached(t *testing.T) {
530		s := NewStore()
531		s.Publish("acme", 0, []Policy{allowPolicy("p1", "u1", "read", "org/a", false)})
532		s.Decide("acme", request("acme", "u1", "r1", "org/a", "read"))
533		before, beforeCP, _ := s.AuditExport("acme", 0)
534	
535		recs, cp, _ := s.AuditExport("acme", 0)
536		snapshot := cloneExportedRecords(recs)
537		archive, err := EncodeAuditArchive("acme", recs, cp)
538		if err != nil {
539			t.Fatal(err)
540		}
541		if !reflect.DeepEqual(recs, snapshot) {
542			t.Fatal("encode mutated the supplied records")
543		}
544		// Encode/decode append nothing to any service state.
545		after, afterCP, _ := s.AuditExport("acme", 0)
546		if !reflect.DeepEqual(after, before) || afterCP != beforeCP {
547			t.Fatal("archive operations changed service state")
548		}
549	
550		got, err := DecodeAuditArchive(archive, "acme", cp)
551		if err != nil {
552			t.Fatal(err)
553		}
554		// Mutating the input bytes after decode cannot reach a prior result.
555		for i := range archive {
556			archive[i] = 0
557		}
558		if got[0].Change.Policies[0].ID != "p1" {
559			t.Fatal("decoded records alias the archive input bytes")
560		}
561		// Mutating one decoded result cannot affect a later decode.
562		got[0].Change.Policies[0].ID = "hacker"
563		got[1].Decision.Request.Subject.ID = "hacker"
564		got[1].Decision.Decision.Matched = append(got[1].Decision.Decision.Matched, "x")
565		fresh, err := EncodeAuditArchive("acme", recs, cp)
566		if err != nil {
567			t.Fatal(err)
568		}
569		again, err := DecodeAuditArchive(fresh, "acme", cp)
570		if err != nil {
571			t.Fatal(err)
572		}
573		if !reflect.DeepEqual(again, recs) {
574			t.Fatal("mutation of one decoded result reached another decode")
575		}
576	}
577	
578	// TestArchiveRoundTripAfterInstanceEnds simulates the stated lifecycle:
579	// export and archive on one instance, then (with no Store at all) read the
580	// bytes elsewhere and continue offline review against the retained
581	// checkpoint.
582	func TestArchiveRoundTripAfterInstanceEnds(t *testing.T) {
583		first := NewStore()
584		first.Publish("acme", 0, []Policy{
585			{ID: "p1", Subject: "u1", Action: "read", Scope: "org/a", Effect: EffectAllow, ResourceID: " r 1 "},
586		})
587		original := first.Decide("acme", request("acme", "u1", " r 1 ", "org/a", "read"))
588		recs, cp, err := first.AuditExport("acme", 0)
589		if err != nil {
590			t.Fatal(err)
591		}
592		saved, err := EncodeAuditArchive("acme", recs, cp)
593		if err != nil {
594			t.Fatal(err)
595		}
596	
597		// New instance, no Store involved in decoding.
598		loaded, err := DecodeAuditArchive(saved, "acme", cp)
599		if err != nil {
600			t.Fatalf("read after instance end: %v", err)
601		}
602		review, err := RecheckDecisionOffline("acme", loaded, cp, 2)
603		if err != nil {
604			t.Fatal(err)
605		}
606		if !review.Consistent || !reflect.DeepEqual(review.Original, original) {
607			t.Fatalf("post-restart review = %+v, original %+v", review, original)
608		}
609	}
