289		// Subject-filtered records are not a complete export.
290		page, err := s.AuditQuery("acme", 1, 10, AuditDecision, "u1")
291		if err != nil {
292			t.Fatal(err)
293		}
294		if _, err := RecheckDecisionOffline("acme", page.Records, fullCP, 2); !errors.Is(err, ErrInvalidRange) {
295			t.Fatalf("subject-filtered export err = %v", err)
296		}
297	
298		// A fragment missing the beginning cannot validate.
299		if _, err := RecheckDecisionOffline("acme", full[1:], fullCP, 2); !errors.Is(err, ErrInvalidRange) {
300			t.Fatalf("fragment export err = %v", err)
301		}
302	
303		// The prefix records do not validate against the later checkpoint.
304		if _, err := RecheckDecisionOffline("acme", prefix, fullCP, 2); !errors.Is(err, ErrInvalidRange) {
305			t.Fatalf("prefix with foreign checkpoint err = %v", err)
306		}
307	}
